const paymentPolls=new Map();
const stripeMode=mode=>['stripe_test','stripe_live'].includes(mode);
const modeName=mode=>mode==='stripe_live'?'Live Stripe':mode==='stripe_test'?'Stripe sandbox':'Simulated';
'use strict';
const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const accentInk=hex=>{const rgb=hex.slice(1).match(/../g).map(v=>parseInt(v,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722>.179?'#000000':'#ffffff';};
const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:n%100?2:0}).format(n/100);
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join('');
const icon=(type)=>{const shapes={arrow:'<path d="M6 18 18 6M6 6h12v12"/>',home:'<path d="m3 10 9-7 9 7v11H3V10Zm6 11v-8h6v8"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v5m10-5v5M3 11h18"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M2 21v-3a7 7 0 0 1 14 0v3m1-18a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5v3"/>',check:'<path d="m4 12 5 5L20 6"/>',mail:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="m3 7 9 6 9-6"/>',wallet:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M3 8h18m-4 5h4"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',pin:'<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">${shapes[type]||shapes.home}</svg>`;};
let authReturnPath=null;
let resetToken='';
let me=null,csrf=null,config={},publicData=null,dashboardData=null,pendingBlock=null,routeVersion=0,authIntent=null;
async function api(path,{method='GET',body}={}){const response=await fetch(path,{method,headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{})},body:body===undefined?undefined:JSON.stringify(body)});let result;try{result=await response.json();}catch{throw new Error('The server is unavailable. Please try again.');}if(!response.ok){const error=new Error(result.error||'Something went wrong.');error.status=response.status;throw error;}return result;}
async function refreshMe(){const result=await api('/api/me');me=result.user;csrf=result.csrf;config=result;$('modeBar').innerHTML=`<strong>PUBLIC BOOKING SITE</strong> · ${config.payment_mode==='stripe_live'?'LIVE CARD PAYMENTS':config.payment_mode==='demo'?'SIMULATED PAYMENTS':'STRIPE SANDBOX'} · ${config.email_mode==='preview'?'EMAIL PREVIEWS':'EMAIL DELIVERY ENABLED'}`;}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4800);}
function modal(title,content,{wide=false,eyebrow='FITSPACE'}={}){$('modal').classList.toggle('wide',wide);$('modalEyebrow').textContent=eyebrow;$('modalBody').innerHTML=`<div class="modal-content"><h2 id="modalTitle">${esc(title)}</h2>${content}<div class="modal-error" id="modalError"></div></div>`;if(!$('modal').open)$('modal').showModal();}
function modalError(message){$('modalError').innerHTML=`<div class="error-box" role="alert">${esc(message)}</div>`;$('modalError').scrollIntoView({block:'nearest'});}
function navigate(path){if(!path.startsWith('/')||path.startsWith('//'))return;history.pushState(null,'',path);if($('modal').open)$('modal').close();renderRoute();window.scrollTo(0,0);}
function dateText(local,long=false){return new Date(local+'Z').toLocaleDateString('en-GB',{timeZone:'UTC',day:'numeric',month:long?'long':'short',...(long?{weekday:'long',year:'numeric'}:{})});}
function timeText(local){return local.slice(11,16);}
function statusPill(status,mode){const names={pending:'Checkout in progress',paid:mode==='stripe_live'?'Confirmed':mode==='demo'?'Test confirmed':'Sandbox confirmed',cancelled:'Cancelled',expired:'Expired',failed:'Payment failed',review:'Payment needs review',attended:'Attended',no_show:'No show',unmarked:'Unmarked',refunded:'Refunded',preview:'Preview only',queued:'Queued',sent:'Sent'};const colour=['paid','attended','sent'].includes(status)?'green':['failed','no_show','review'].includes(status)?'red':['pending','queued'].includes(status)?'':'grey';return `<span class="pill ${colour}">${names[status]||esc(status)}</span>`;}
function resetTheme(){const styles=document.documentElement.style;for(const [name,value]of Object.entries({'--accent':'#ffd43b','--accent-ink':'#111','--bg':'#fff','--fg':'#141414'}))styles.setProperty(name,value);}
function theme(pt){document.documentElement.style.setProperty('--accent',pt.accent);document.documentElement.style.setProperty('--bg',pt.background);document.documentElement.style.setProperty('--fg',pt.foreground);document.documentElement.style.setProperty('--accent-ink',accentInk(pt.accent));}
function brandHeader(pt=null){const brand=pt?.brand_name||'FITSPACE';return `<header class="header"><a class="brand" href="${pt?'/pt/'+esc(pt.slug):'/'}" data-route><span class="brand-icon">${pt?(brand==='SIX WEEK CLUB'?'6':esc(Array.from(brand)[0].toUpperCase())):'F'}</span>${esc(brand)}</a><nav class="nav" aria-label="Main navigation"><a href="/trainers" class="optional" data-route>Find a trainer</a>${me?`<a href="/dashboard" data-route>${me.role==='customer'?'My bookings':'Dashboard'}</a><button class="text-btn optional" data-action="logout">Sign out</button>`:`<button class="text-btn" data-action="login">Sign in</button><button class="btn accent small" data-action="signup">Sign up ${icon('arrow')}</button>`}</nav></header>`;}
const footer=()=>`<footer class="footer"><div>TRAIN WITH PURPOSE. BUILD YOUR CONFIDENCE.<br>${config.payment_mode==='stripe_live'?'Secure card payments through Stripe.':'Test payments only. No real money is collected.'}</div><a href="/trainers" data-route>Discover another trainer ↗</a></footer>`;
function classCard(block,index,{manage=false}={}){const first=block.sessions[0],last=block.sessions.at(-1),n=block.sessions.length;const remaining=block.available;return `<article class="block-card"><div class="card-top"><span>${manage?block.closed?'CLOSED':block.published?'PUBLISHED':'DRAFT':`BLOCK ${String(index+1).padStart(2,'0')}`} / MAX ${block.capacity}</span><span class="pill ${remaining===0?'grey':''}">${remaining===0?'Fully booked':`${remaining} ${remaining===1?'place':'places'} left`}</span></div><h3>${esc(block.title)}</h3><p>${esc(block.description)}</p><div class="class-details"><span>${icon('calendar')}${first?dateText(first.starts_at):'No dates'}${n>1?' – '+dateText(last.starts_at):''}</span><span>${icon('clock')}${first?timeText(first.starts_at):'—'} · ${first?.duration_minutes||60} min</span><span>${icon('people')}${n} ${n===1?'session':'sessions'} · one place per booking</span><span>${icon('pin')}${esc(block.venue)}</span></div><details class="schedule"><summary>See ${n===1?'the session date':`all ${n} session dates`}</summary><div class="date-list">${block.sessions.map(s=>`<span>${dateText(s.starts_at)} · ${timeText(s.starts_at)}</span>`).join('')}</div></details><div class="capacity-row"><span>${block.paid_count} confirmed / ${block.capacity} capacity</span><span>${block.capacity-remaining-block.paid_count} in checkout</span></div><div class="track"><div style="width:${(block.capacity-remaining)/block.capacity*100}%"></div></div><div class="card-bottom"><div class="price">${money(block.price_pence)}<small>${n===1?'One session':`All ${n} sessions`} · paid upfront</small></div>${manage?`<button class="btn outline small" data-action="edit-block" data-id="${block.id}">Edit class ${icon('arrow')}</button>`:`<button class="btn accent" data-action="book" data-id="${block.id}" ${!remaining||!block.can_book?'disabled':''}>${remaining?'Book your place':'Block full'} ${icon('arrow')}</button>`}</div></article>`;}
async function renderHome(slug,version){const result=await api('/api/public/pts/'+encodeURIComponent(slug));if(version!==routeVersion)return;publicData=result;const {pt,blocks}=result;theme(pt);document.title=pt.brand_name+' — Classes & training';const min=blocks.length?Math.min(...blocks.map(b=>b.capacity)):15,max=blocks.length?Math.max(...blocks.map(b=>b.capacity)):15;const limited=min===max?`LIMITED TO ${max} PEOPLE PER CLASS GROUP`:`SMALL GROUPS · ${min}–${max} PLACES PER BLOCK`;$('app').innerHTML=`<div class="tenant"><div class="container">${brandHeader(pt)}<main><section class="hero"><div><div class="eyebrow">TRAIN WITH PURPOSE. BUILD CONFIDENCE.</div><h1>${esc(pt.tagline)}</h1><p>${esc(pt.description)}</p><div class="limit-label">${limited}</div><a class="btn accent" href="#classes">Choose your class or block ${icon('arrow')}</a><div class="hero-note">${icon('check')}One account. Your training. Your next step.</div></div><div class="hero-mark" aria-hidden="true"><span class="top-caption">INVEST IN YOURSELF</span><span class="symbol">↗</span><div class="bottom-caption"><span>TRAIN. GROW. REPEAT.</span><span>AT YOUR PACE</span></div></div></section><div class="feature-strip">${pt.features.map((feature,i)=>`<div>${icon(['check','people','calendar'][i])}<span>${esc(feature)}</span></div>`).join('')}</div><section id="classes"><div class="section-top"><div><div class="eyebrow">LIMITED SPACES / PERSONAL COACHING</div><h2>Your place. Your progress.</h2><p>Book a whole block or a single class. The dates and total price are shown below.</p></div><div class="side-note muted" style="font-size:11px">Pay upfront. No recurring subscription.<br>Places include active checkout reservations.</div></div><div class="card-grid">${blocks.length?blocks.map((b,i)=>classCard(b,i)).join(''):'<div class="empty">New classes are on the way. Create an account so you are ready to book.</div>'}</div></section><section class="training"><div class="eyebrow">MORE THAN A WEEKLY WORKOUT</div><h2>Train well.<br>Build your confidence.</h2><p>${esc(pt.about)}</p><div class="training-highlights">${pt.features.map((feature,i)=>`<div><strong>0${i+1} / ${esc(feature)}</strong><p>${['Practise consistently and focus on progress you can build on.','Your coach and group help keep you encouraged and accountable.','Invest in yourself, one session and one small step at a time.'][i]}</p></div>`).join('')}</div><div class="signup-cta"><p>${me?'Ready to make time for your next workout?':'Your next chapter starts with an account. Sign up, pick a class and take your first step.'}</p>${me?'<a href="#classes" class="btn accent">Find your place ↗</a>':'<button class="btn accent" data-action="signup">Create your customer account ↗</button>'}</div></section></main>${footer()}</div></div>`;}
async function renderDirectory(version){const data=await api('/api/public/pts');if(version!==routeVersion)return;resetTheme();$('app').innerHTML=`<div class="container">${brandHeader()}<main class="directory"><div class="eyebrow">YOUR TRAINING, YOUR WAY</div><h1>Find your coach.<br>Make your next move.</h1><p class="muted">Each trainer has their own classes, schedule and training space.</p><div class="trainer-grid">${data.pts.length?data.pts.map(pt=>`<article class="trainer-card" style="background:${pt.background};color:${pt.foreground};--accent:${pt.accent};--accent-ink:${accentInk(pt.accent)}"><div class="swatches"><span style="background:${pt.accent}"></span></div><h3>${esc(pt.brand_name)}</h3><p style="color:inherit">${esc(pt.description)}</p><a class="btn accent" href="/pt/${pt.slug}" data-route>Visit the trainer's site ↗</a></article>`).join(''):'<p class="empty">Trainer pages and classes are coming soon.</p>'}</div></main>${footer()}</div>`;}
function authModal(mode='login',intent=null){if(intent)authIntent=intent;modal(mode==='signup'?'Your next chapter starts here.':'Welcome back.',`<div class="auth-tabs"><button class="${mode==='login'?'active':''}" data-action="login">Sign in</button><button class="${mode==='signup'?'active':''}" data-action="signup">Create customer account</button></div><p class="muted" style="font-size:12px">${mode==='signup'?'Create an account to book classes, pay upfront and keep all your sessions in one place.':'Sign in to your customer, PT or admin account.'}</p><form data-form="${mode}"><div class="form-grid">${mode==='signup'?'<label class="wide-field">Your name<input name="name" required minlength="2" maxlength="80" autocomplete="name"></label>':''}<label class="wide-field">Email address<input name="email" type="email" required autocomplete="email"></label><label class="wide-field">Password<input name="password" type="password" required ${mode==='signup'?'minlength="12"':''} maxlength="200" autocomplete="${mode==='signup'?'new-password':'current-password'}">${mode==='signup'?'<small class="form-help">At least 12 characters.</small>':''}</label></div>${mode==='signup'?'<label class="check-label"><input type="checkbox" name="demo_acknowledged" required><span>I agree to create a booking account and provide accurate contact details for my classes.</span></label>':''}<button type="submit" class="btn accent full">${mode==='signup'?'Create my customer account':'Sign in'} ↗</button>${mode==='login'?'<button type="button" class="text-btn" data-action="forgot-password">Forgot your password?</button>':''}</form>}`,{eyebrow:'YOUR TRAINING ACCOUNT'});}
function forgotPasswordView(){return `<div class="container">${brandHeader()}<main class="checkout-shell"><div class="eyebrow">CUSTOMERS & PERSONAL TRAINERS</div><h1>Get back to your training.</h1><p>Enter the email address on your account to request a password reset. Links expire after 30 minutes.</p>${config.password_reset_available?`<div class="panel"><form data-form="forgot-password"><label>Email address<input type="email" name="email" required autocomplete="email" maxlength="160"></label><button type="submit" class="btn accent full">Email my reset link</button></form><div id="resetFeedback" role="status"></div></div>`:'<div class="info-box">Password reset emails are not configured yet. Contact your trainer or the platform owner for help.</div>'}<a class="text-btn" href="/login" data-route>Back to sign in</a></main></div>`;}
function resetPasswordView(){return `<div class="container">${brandHeader()}<main class="checkout-shell"><div class="eyebrow">YOUR TRAINING ACCOUNT</div><h1>Choose a new password.</h1>${resetToken?`<p>Your new password must contain 12–200 characters. You will be signed out on all devices.</p><div class="panel"><form data-form="reset-password"><label>New password<input type="password" name="new_password" required minlength="12" maxlength="200" autocomplete="new-password"></label><label>Confirm new password<input type="password" name="confirm_password" required minlength="12" maxlength="200" autocomplete="new-password"></label><button type="submit" class="btn accent full">Save new password</button></form><div id="resetFeedback" role="status"></div></div>`:'<div class="info-box">Open the complete reset link from your email, or request a fresh link.</div>'}<a href="/forgot-password" class="text-btn" data-route>Request a new reset link</a></main></div>`;}
function bookingModal(block){pendingBlock=block;if(!me)return authModal('signup','book');if(me.role!=='customer'){toast('Use a customer account to book a class.');return;}modal('Make time for your progress.',`<p>Your place covers ${block.sessions.length===1?'this session':`all ${block.sessions.length} sessions`} in ${esc(block.title)}.</p><dl class="summary-lines"><div><dt>Customer</dt><dd>${esc(me.name)}</dd></div><div><dt>Email</dt><dd>${esc(me.email)}</dd></div><div><dt>Sessions</dt><dd>${block.sessions.length} · dates shown below</dd></div><div><dt>Remaining places</dt><dd>${block.available} of ${block.capacity}</dd></div><div class="total"><dt>Upfront total</dt><dd>${money(block.price_pence)}</dd></div></dl><div class="date-list">${block.sessions.map(s=>`<span>${dateText(s.starts_at)} · ${timeText(s.starts_at)}</span>`).join('')}</div><form data-form="reserve"><input type="hidden" name="block_id" value="${block.id}"><input type="hidden" name="checkout_token" value="${uid()}"><label class="check-label"><input type="checkbox" required><span>${config.payment_mode==='stripe_live'?'This is a real card payment for the full block price shown above.':'This is a test payment. No real charge will be made.'} A place is held for up to 35 minutes and confirmed only after verified payment.</span></label><button type="submit" class="btn accent full">Continue to ${modeName(config.payment_mode)} checkout · ${money(block.price_pence)} ↗</button></form>`,{eyebrow:'YOUR CLASS BOOKING'});}
async function renderCheckout(id,version,confirmationPage=false){
 if(!me){authReturnPath=location.pathname;authModal('login','return');return renderDirectory(version);}
 const result=await api('/api/bookings/'+id);if(version!==routeVersion)return;
 resetTheme();const b=result.booking,isPaid=b.status==='paid',refunded=b.refund_status==='succeeded';
 const intro=refunded?'This payment has been fully refunded. Your place has been released.':b.status==='review'?'Stripe reported a payment after this reservation ended. Your place is not confirmed. Contact the trainer to arrange a refund.':isPaid?'Your place is confirmed for every session in this booking.':b.status==='pending'?'Your place is held while checkout is active. A Stripe booking is confirmed only after its signed payment notification arrives.':'This checkout has ended. Choose a new class or block to try again.';
 document.title=(isPaid?'Booking confirmed':refunded?'Payment refunded':'Your checkout')+' — FITSPACE';
 $('app').innerHTML=`<div class="container">${brandHeader()}</div><main class="checkout-shell">${isPaid?'<div class="success-mark">✓</div>':'<div class="eyebrow">ONE PLACE. ONE UPFRONT PAYMENT.</div>'}<h1>${refunded?'Payment refunded.':isPaid?`You're in, ${esc(b.customer_name.split(' ')[0])}.`:b.status==='review'?'Your payment needs a review.':confirmationPage&&b.status==='pending'?'Waiting for Stripe confirmation…':'Your next step starts here.'}</h1><p class="muted">${intro}</p><div class="checkout-grid"><div><div class="panel"><div class="eyebrow">${esc(b.brand_name)}</div><h2 style="font-size:27px">${esc(b.title)}</h2><p class="muted" style="font-size:12px">${esc(b.venue)} · all times UK time</p><ul class="session-timeline">${b.sessions.map(s=>`<li>${dateText(s.starts_at,true)} · ${timeText(s.starts_at)}<small>${s.duration_minutes} minutes</small></li>`).join('')}</ul><small class="muted">Reference: ${esc(b.reference)}</small></div></div><div><div class="panel"><dl class="summary-lines"><div><dt>Customer</dt><dd>${esc(b.customer_name)}</dd></div><div><dt>Includes</dt><dd>${b.sessions.length} sessions · one place</dd></div><div><dt>Booking fee</dt><dd>£0</dd></div><div class="total"><dt>Total upfront</dt><dd>${money(b.amount_pence)}</dd></div>${b.refunded_pence?`<div><dt>Refunded</dt><dd>${money(b.refunded_pence)}</dd></div>`:''}</dl>${statusPill(refunded?'refunded':b.status,b.mode)}<p class="fine">${modeName(b.mode)} payment · ${b.mode==='stripe_live'?'real money':'no real money charged'}.</p>${b.payment_error?`<div class="info-box">${esc(b.payment_error)}</div>`:''}${b.refund_status==='pending'?'<div class="info-box">Stripe is processing the refund. The booking remains active until the refund succeeds.</div>':b.refund_status==='requested'?'<div class="info-box">The refund request is saved. If the connection was interrupted, the trainer can retry it safely using its existing payment-operation key.</div>':''}${b.refund_error?`<div class="info-box">${esc(b.refund_error)}</div>`:''}${b.status==='pending'&&b.mode==='demo'?`<div class="info-box"><strong>Test checkout</strong><br>No card details needed. Choose an outcome to test the booking journey.</div><button class="btn accent full" data-action="pay-demo" data-id="${b.id}" data-result="success">Complete test payment · ${money(b.amount_pence)} ↗</button><button class="btn outline full" data-action="pay-demo" data-id="${b.id}" data-result="declined">Try declined payment</button>`:b.status==='pending'?`<div class="info-box">${b.mode==='stripe_live'?'Stripe will charge your card the full upfront total shown above.':'Use Stripe test card details only.'} Returning from Stripe does not confirm your place until the signed notification has been received.</div><button class="btn accent full" data-action="resume-stripe" data-id="${b.id}">Continue to ${modeName(b.mode)} ↗</button><button class="btn outline full" data-action="refresh-route">Refresh payment status</button>`:isPaid?`<div class="info-box"><strong>See you at class.</strong><br>Your confirmation email is saved as a preview. Bring water, trainers and comfortable workout clothes.</div><a class="btn accent full" href="/dashboard" data-route>See my bookings ↗</a>`:`<a class="btn accent full" href="/pt/${b.slug}" data-route>Choose another class ↗</a>`}${b.status==='pending'?`<button class="text-btn" data-action="cancel-booking" data-id="${b.id}">Cancel checkout</button>`:''}${!['customer'].includes(me.role)&&stripeMode(b.mode)&&b.mode===config.payment_mode&&b.payment_intent&&['paid','review'].includes(b.status)&&b.refund_status!=='pending'?`<button class="btn outline full" data-action="refund-booking" data-id="${b.id}">Refund remaining payment</button>`:''}</div></div></div></main>`;
 if(confirmationPage&&b.status==='pending'&&stripeMode(b.mode)&&b.mode===config.payment_mode){
  const count=paymentPolls.get(id)||0;if(count<20){paymentPolls.set(id,count+1);setTimeout(()=>{if(routeVersion===version)renderRoute();},3000);}
 }
}
function dashboardShell(tab,content){const role=me.role;const tabs=role==='pt'?[['overview','home','Overview'],['classes','calendar','Classes & blocks'],['bookings','people','Bookings'],['attendance','check','Attendance'],['messages','mail','Messages'],['payments','wallet','Payments'],['account','settings','My account']]:role==='admin'?[['overview','home','Overview'],['trainers','people','PT accounts'],['branding','settings','Branding & pages'],['bookings','people','Bookings & refunds'],['stripe','wallet','Stripe setup'],['classes','calendar','Class blocks'],['messages','mail','Email previews'],['quotes','check','Motivational replies'],['account','settings','My account']]:[['bookings','calendar','My bookings'],['trainers','people','Find a trainer'],['account','settings','My account']];return `<div class="dashboard"><aside class="sidebar"><a class="brand" href="/" data-route><span class="brand-icon">F</span>FITSPACE</a><div class="role-label">${role==='pt'?'TRAINER WORKSPACE':role==='admin'?'PLATFORM ADMIN':'YOUR TRAINING'}</div><nav class="side-nav" aria-label="Dashboard navigation">${tabs.map(([id,ic,label])=>`<a href="/dashboard?tab=${id}" data-route class="side-link ${tab===id?'active':''}">${icon(ic)}${label}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="user-name">${esc(me.name)}</div><div class="user-email">${esc(me.email)}</div><button class="text-btn" data-action="logout">Sign out</button></div></aside><main class="workspace"><header class="work-header"><div class="breadcrumb">${role==='pt'?esc(dashboardData.pt.brand_name):role==='admin'?'Your coaching platform':'Your customer account'} / ${esc(tabs.find(t=>t[0]===tab)?.[2]||tab)}</div><div class="header-actions">${role==='pt'?`<a href="/pt/${dashboardData.pt.slug}" class="btn outline small" data-route>View my site ↗</a>`:'<a href="/trainers" class="btn outline small" data-route>Browse classes ↗</a>'}<button class="text-btn" data-action="logout">Sign out</button></div></header>${me.must_change_password?'<div class="info-box"><strong>Set your own password.</strong> You are using a temporary password. <button class="text-btn" data-action="password">Change it now</button> before managing classes.</div>':''}${content}</main></div>`;}
function heading(title,copy,button=''){return `<div class="work-title"><div><h1>${title}</h1><p>${copy}</p></div>${button}</div>`;}
function stats(items){return `<div class="stats">${items.map(([label,value,note])=>`<div class="stat"><span>${label}</span><strong>${value}</strong><small>${note||''}</small></div>`).join('')}</div>`;}
async function ptStripeView(){const setup=await api('/api/pt/stripe/setup');return heading('Your Stripe. Your class payments.','Use your own Stripe account. The website owner does not need a Stripe account.')+stats([['Net collected',money(dashboardData.stats.revenue_pence),'Current mode · after refunds · before fees'],['Refunds',money(dashboardData.stats.refunds_pence||0),'Current mode'],['Site payment mode',modeName(config.payment_mode),'Owner chooses deployment mode'],['Sandbox payment + refund',setup.sandbox_passed?'Passed':'To complete','Required before enabling live']])+`${!setup.encryption_ready||!setup.app_url_ready?'<div class="info-box">The owner must configure CREDENTIAL_ENCRYPTION_KEY and a canonical HTTPS APP_URL in Netlify before setup is complete.</div>':''}<div class="panel"><h2>Set up your account</h2><ol><li>In your own Stripe sandbox, create a restricted API key.</li><li>Save the key below. Copy your webhook URL into Stripe Workbench → Webhooks → Your account → Snapshot events.</li><li>Subscribe to the listed events, then save that endpoint’s signing secret.</li><li>Check account status, enable sandbox payments and complete a booking and full refund.</li><li>Set up live separately when ready for genuine purchases.</li></ol><p>The full class price comes from your saved booking settings. A £90 block creates one £90 charge. Stripe fees reduce your payout; FITSPACE adds no application fee.</p><details><summary>Permissions and payment events</summary><p>Restricted key starting permissions: ${setup.permissions.map(([n,p])=>esc(n)+' — '+esc(p)).join('; ')}. Complete sandbox checkout and refund to validate all permissions; if Stripe reports an additional required resource, grant only that permission.</p><p>Webhook events: ${setup.events.map(esc).join(', ')}. Each received event is verified with your signing secret and retrieved from your account using the restricted key. Events permission is required.</p></details></div><div class="card-grid">${['stripe_test','stripe_live'].map(mode=>{const c=setup.accounts.find(c=>c.mode===mode),live=mode==='stripe_live';return `<section class="panel"><div class="eyebrow">${live?'GENUINE CARD PAYMENTS':'NO REAL MONEY'}</div><h2>${modeName(mode)}</h2><p>${c?`Account: <strong>${esc(c.account_id)}</strong><br>${c.enabled?'New payments enabled':'New payments paused'} · ${c.charges_ready?'Card payments ready':'Card setup needed'}<br>${c.payouts_ready?'Payouts enabled':'Check payout requirements in Stripe'}<br>${c.webhook_seen_at?'Verified webhook received':'Awaiting your first verified event'}`:'No account saved for this mode.'}</p><form data-form="pt-stripe"><input type="hidden" name="mode" value="${mode}"><label>Restricted API key<input type="password" name="api_key" autocomplete="off" maxlength="256" ${c?.configured?'':'required'} placeholder="${c?.configured?'Leave blank to keep saved key':live?'rk_live_…':'rk_test_…'}"></label><label>Webhook signing secret<input type="password" name="webhook_secret" autocomplete="off" maxlength="256" placeholder="${c?.webhook_configured?'Leave blank to keep saved secret':'whsec_… — add after creating endpoint'}"></label><p class="fine">Saved secrets are never shown. Saving changes pauses new payments until you enable them again.</p><button type="submit" class="btn accent full" ${!setup.encryption_ready?'disabled':''}>Save and verify account</button></form>${c?`<label>Your webhook URL<input type="text" readonly value="${esc(c.webhook_url)}"></label><div class="list-actions"><button class="btn outline small" data-action="pt-stripe-check" data-mode="${mode}">Check account status</button><button class="btn outline small" data-action="pt-stripe-enable" data-mode="${mode}" ${!c.configured||!c.webhook_configured||!c.charges_ready||live&&!setup.sandbox_passed?'disabled':''}>${live?'Enable live payments':'Enable sandbox payments'}</button><button class="text-btn" data-action="pt-stripe-pause" data-mode="${mode}">Pause new payments</button><button class="text-btn" data-action="pt-stripe-remove" data-mode="${mode}" data-account="${esc(c.account_id)}">Remove credentials</button></div>`:''}<p class="fine">${live?'Live requires a verified sandbox booking and full refund, plus explicit confirmation. The site must also be deployed in live mode.':'A saved webhook secret is configuration only. Verify delivery with a genuine sandbox checkout before live use.'}</p></section>`;}).join('')}</div>`;}
async function stripeSetupView(){const setup=await api('/api/admin/stripe/setup');if(setup.integration==='pt_direct')return heading('PT-owned Stripe accounts.','No owner Stripe account or platform key is required. Each PT configures their own Payments page.')+`<div class="panel"><dl class="summary-lines"><div><dt>Credential encryption</dt><dd>${setup.encryption_ready?'Configured':'Needs CREDENTIAL_ENCRYPTION_KEY'}</dd></div><div><dt>Canonical HTTPS URL</dt><dd>${setup.app_url_ready?'Configured':'Needs APP_URL'}</dd></div><div><dt>Site payment mode</dt><dd>${modeName(setup.mode)}</dd></div></dl><p>Configure CREDENTIAL_ENCRYPTION_KEY in Netlify Functions as 64 random hexadecimal characters. Keep it backed up and stable. PT credentials are encrypted in the database and never returned to this dashboard. Each PT adds their own restricted key and webhook signing secret.</p><h3>Trainer connections</h3>${setup.connections.length?setup.connections.map(c=>`<p>${esc(dashboardData.pts.find(p=>p.id===c.pt_id)?.brand_name||'Trainer')} · ${modeName(c.mode)} · ${esc(c.account_id)} · ${c.enabled?'New payments enabled':'Paused / setup needed'} · ${c.webhook_seen_at?'Webhook received':'Awaiting verified webhook'}</p>`).join(''):'<p>No PTs have configured Stripe yet.</p>'}</div>`;return heading('Stripe account setup.','Each PT connects from their own Payments page. Keys are configured in Netlify, never entered here.')+`<div class="panel"><h2>${modeName(setup.mode)}</h2><dl class="summary-lines"><div><dt>Server key matches mode</dt><dd>${setup.key_ready?'Ready':'Needs configuration'}</dd></div><div><dt>Webhook secret configured</dt><dd>${setup.webhook_ready?'Yes':'No'}</dd></div><div><dt>Connect webhook secret</dt><dd>${setup.connect_webhook_ready?'Yes':'Uses main secret'}</dd></div><div><dt>HTTPS app URL</dt><dd>${setup.app_url_ready?'Ready':'Needs configuration'}</dd></div></dl><p>Set PAYMENT_MODE, STRIPE_SECRET_KEY, STRIPE_WEBHOOK_SECRET and APP_URL in Netlify’s Functions environment, then redeploy. For multiple trainers enable Stripe Connect and subscribe to connected-account payment events. A configured secret is not proof of webhook delivery: complete the sandbox checklist before switching live.</p><button class="btn accent" data-action="stripe-check-owner">Check server Stripe account</button><h3 style="margin-top:30px">Connected trainers</h3>${setup.connections.map(c=>`<p>${esc(c.brand_name)} · ${modeName(c.mode)} · ${esc(c.account_id)} · ${c.ready?'Ready':'Setup needed'}</p>`).join('')||'<p>No accounts connected yet.</p>'}<details><summary>Use the platform owner’s Stripe account for one trainer</summary><p>Optional for your own training business. Other PTs should use their own Connect onboarding.</p><label>Trainer<select id="stripeTrainer"><option value="">Choose trainer</option>${dashboardData.pts.map(p=>`<option value="${esc(p.id)}">${esc(p.brand_name)}</option>`).join('')}</select></label><button class="btn outline" data-action="stripe-link-owner">Link server Stripe account</button></details></div>`;}
function accountView(){return heading('Your account.','Manage your sign-in details.')+`<div class="panel" style="max-width:570px"><dl class="summary-lines"><div><dt>Name</dt><dd>${esc(me.name)}</dd></div><div><dt>Email</dt><dd>${esc(me.email)}</dd></div><div><dt>Profile type</dt><dd>${me.role==='pt'?'Personal trainer':me.role==='admin'?'Platform admin':'Customer'}</dd></div></dl><button class="btn" data-action="password">Change password</button><p class="fine">${me.role==='admin'?`Customer and PT reset emails: ${config.password_reset_available?'configured':'not configured — see PASSWORD_RESET_SETUP.md'}.`:'If you forget your password, use the reset link on the sign-in page.'}</p></div>`;}
function bookingTable(bookings,customer=false){if(!bookings.length)return '<div class="empty">No bookings yet. Your next session could start with one small step.</div>';return `<div class="toolbar"><label class="sr-only" for="bookingSearch">Search bookings</label><input id="bookingSearch" type="search" placeholder="Search customer, class or reference"></div><div class="table-wrap"><table><thead><tr><th>${customer?'Trainer / class':'Customer'}</th><th>${customer?'First session':'Class / reference'}</th><th>Payment</th><th>Status</th><th>Action</th></tr></thead><tbody id="bookingsBody">${bookings.map(b=>`<tr data-search="${esc((b.customer_name+' '+b.customer_email+' '+b.title+' '+b.reference).toLowerCase())}"><td><strong>${esc(customer?b.brand_name:b.customer_name)}</strong><small>${esc(customer?b.title:b.customer_email)}</small></td><td><strong>${customer?dateText(b.sessions[0].starts_at):esc(b.title)}</strong><small>${customer?timeText(b.sessions[0].starts_at):esc(b.reference)}</small></td><td>${money(b.amount_pence)}<br><small>${modeName(b.mode)}</small></td><td>${statusPill(b.refund_status==='succeeded'?'refunded':b.status,b.mode)}${b.refunded_pence?`<small>Refunded ${money(b.refunded_pence)}</small>`:''}${['requested','pending'].includes(b.refund_status)?'<small>Refund pending</small>':''}</td><td><a href="/${b.status==='pending'?'checkout':'booking'}/${b.id}" class="btn outline small" data-route>View</a>${(['paid','pending'].includes(b.status)&&b.mode==='demo')||(b.status==='pending'&&stripeMode(b.mode)&&b.mode===config.payment_mode)?` <button class="text-btn" data-action="cancel-booking" data-id="${b.id}">Cancel</button>`:''}${!customer&&stripeMode(b.mode)&&b.mode===config.payment_mode&&b.payment_intent&&['paid','review'].includes(b.status)&&b.refund_status!=='pending'?` <button class="text-btn" data-action="refund-booking" data-id="${b.id}">Refund payment</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;}
function messageTable(rows){if(!rows.length)return '<div class="empty">No messages yet. Booking confirmations and no-show follow-ups will appear here.</div>';return `<div class="info-box">${config.email_mode==='preview'?'Messages are saved as previews. No emails are sent until a provider and verified sender are configured.':'Messages are queued for your configured email service. Check status below; failed deliveries are retried.'}</div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Subject</th><th>Type</th><th>Status</th><th>Preview</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${esc(m.recipient)}</td><td><strong>${esc(m.subject)}</strong><small>${new Date(m.created_at).toLocaleString('en-GB')}</small></td><td>${m.kind==='no_show'?'No-show follow-up':'Booking confirmation'}</td><td>${statusPill(m.status)}${m.last_error?`<br><small>${esc(m.last_error)}</small>`:''}</td><td><button class="btn outline small" data-action="email-preview" data-id="${m.id}">Read message</button></td></tr>`).join('')}</tbody></table></div>`;}
function trainerCards(pts,brandingTab=false){return `<div class="trainer-grid">${pts.map(pt=>`<article class="trainer-card"><div class="swatches"><span style="background:${pt.accent}"></span><span style="background:${pt.background}"></span><span style="background:${pt.foreground}"></span></div><h3>${esc(pt.brand_name)}</h3><p>${esc(pt.owner_name)} · ${esc(pt.owner_email)}</p><div class="link">/pt/${esc(pt.slug)}</div><p style="margin:12px 0">${pt.blocks.length} classes or blocks · ${pt.published?'Page published in this preview':'Page hidden'}</p><div class="list-actions"><button class="btn small" data-action="edit-brand" data-id="${pt.id}">${brandingTab?'Customise page':'Edit branding'}</button><a class="btn outline small" href="/pt/${pt.slug}" data-route>View site ↗</a><button class="text-btn" data-action="new-block" data-pt="${pt.id}">Add class</button></div></article>`).join('')}</div>`;}
function attendanceView(data){const sessions=data.blocks.flatMap(b=>b.sessions.map(s=>({...s,title:b.title,block_id:b.id}))).sort((a,b)=>b.starts_epoch-a.starts_epoch);return heading('Every session. Every person.','Mark attendance after a session finishes. A no-show creates one supportive follow-up, with one of 20 original motivational replies.')+`<div class="toolbar"><label for="attendanceSession">Session<select id="attendanceSession"><option value="">Choose a class session</option>${sessions.map(s=>`<option value="${s.id}">${esc(s.title)} · ${dateText(s.starts_at)} ${timeText(s.starts_at)}${s.starts_epoch+s.duration_minutes*60000>Date.now()?' · upcoming':''}</option>`).join('')}</select></label></div><div id="attendanceRoster" class="empty">Choose a session to see its confirmed customers.</div>`;}
function renderRoster(sessionId){const session=dashboardData.blocks.flatMap(b=>b.sessions.map(s=>({...s,title:b.title,block_id:b.id}))).find(s=>s.id===sessionId);if(!session){$('attendanceRoster').innerHTML='Choose a session to see its confirmed customers.';return;}const bookings=dashboardData.bookings.filter(b=>b.status==='paid'&&b.block_id===session.block_id);const future=session.starts_epoch+session.duration_minutes*60000>Date.now();$('attendanceRoster').className='';$('attendanceRoster').innerHTML=`${future?'<div class="info-box">Attendance can be marked after this session finishes.</div>':''}${bookings.length?`<div class="table-wrap"><table><thead><tr><th>Customer</th><th>Booking</th><th>Attendance</th><th>Mark attendance</th></tr></thead><tbody>${bookings.map(b=>{const status=b.sessions.find(s=>s.id===sessionId).attendance_status;return `<tr><td><strong>${esc(b.customer_name)}</strong><small>${esc(b.customer_email)}</small></td><td>${esc(b.reference)}</td><td>${statusPill(status)}</td><td><div class="attendance-actions">${[['attended','Present'],['no_show','No show'],['unmarked','Clear']].map(([value,label])=>`<button class="btn ${value==='attended'?'accent':'outline'} ${status===value?'selected':''}" data-action="attendance" data-booking="${b.id}" data-session="${session.id}" data-status="${value}" ${future?'disabled':''}>${label}</button>`).join('')}</div></td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty">There are no confirmed customers for this session.</div>'}`;}
async function renderDashboard(version){if(!me){await renderDirectory(version);authModal('login','dashboard');return;}resetTheme();const data=await api('/api/dashboard');if(version!==routeVersion)return;dashboardData=data;let tab=new URLSearchParams(location.search).get('tab')||(me.role==='customer'?'bookings':'overview'),content='';if(tab==='account')content=accountView();else if(me.role==='customer'){if(tab==='trainers'){navigate('/trainers');return;}content=heading('Make room for your next step.',`Welcome back, ${esc(me.name.split(' ')[0])}. Your bookings and session dates, all in one place.`,`<a class="btn accent" href="/trainers" data-route>Find a class ↗</a>`)+bookingTable(data.bookings,true);}else if(me.role==='pt'){if(tab==='overview'){const next=data.blocks.filter(b=>b.sessions[0]?.starts_epoch>Date.now()).slice(0,3);content=heading(`Keep your clients moving, ${esc(me.name.split(' ')[0])}.`,'Your classes, bookings and follow-ups. One clear view.', '<button class="btn accent" data-action="new-block">Add a class or block +</button>')+stats([['Confirmed bookings',data.stats.confirmed,'All your classes'],['Simulated revenue',money(data.stats.demo_revenue_pence),'No real money collected'],[config.payment_mode==='stripe_live'?'Live Stripe net':'Stripe sandbox net',money(data.stats.revenue_pence),'After refunds · before Stripe fees'],['No-shows',data.stats.no_shows,'Marked attendance']])+`<div class="panel"><div class="panel-head"><div><h2>Your next class blocks</h2><p>Places are shared across customer accounts.</p></div><a class="text-btn" href="/dashboard?tab=classes" data-route>See all classes</a></div><div class="panel-list">${next.length?next.map(b=>`<div class="list-row"><div><strong>${esc(b.title)}</strong><p>${dateText(b.sessions[0].starts_at)} · ${b.sessions.length} sessions · ${b.available} places available</p></div><button class="btn outline small" data-action="edit-block" data-id="${b.id}">Manage</button></div>`).join(''):'<p class="muted">Add your first future class to get started.</p>'}</div></div><div class="info-box">Your own client page: <a href="/pt/${data.pt.slug}" data-route><strong>/pt/${data.pt.slug} ↗</strong></a><br>Share your named page with clients. The platform admin can customise its colours, text and training highlights.</div>`;}else if(tab==='classes')content=heading('Build a schedule that fits.','One-off classes, four-week blocks, six-week programmes or your own format. Set every session date yourself.','<button class="btn accent" data-action="new-block">Add class or block +</button>')+`<div class="card-grid">${data.blocks.map((b,i)=>classCard(b,i,{manage:true})).join('')}</div>`;else if(tab==='bookings')content=heading('Your bookings. Clear and current.','Confirmed places and active checkouts, with customer contact details.')+bookingTable(data.bookings);else if(tab==='attendance')content=attendanceView(data);else if(tab==='messages')content=heading('A little encouragement goes a long way.','View booking confirmations and supportive no-show messages.')+messageTable(data.outbox);else if(tab==='payments')content=config.stripe_integration==='pt_direct'?await ptStripeView():heading('Your Stripe. Your class payments.','Link your account securely with Stripe, then charge the upfront price you set for each class or block.')+stats([['Net collected',money(data.stats.revenue_pence),'Current mode · after refunds · before fees'],['Refunds',money(data.stats.refunds_pence||0),'Current payment mode'],['Confirmed bookings',data.stats.confirmed,'All payment modes'],['Payment mode',modeName(config.payment_mode),config.payment_mode==='stripe_live'?'Real card payments':'Test payments only']])+`<div class="panel"><h2 style="font-size:25px">Connect your Stripe account</h2>${data.pt.stripe_account_id?`<p>Connected account: <strong>${esc(data.pt.stripe_account_id)}</strong></p>`:''}<p class="muted">${data.pt.stripe_ready?'Your Stripe account is ready to receive payments in this mode.':data.pt.stripe_connected?'Your Stripe account is linked. Complete any requirements and check its status.':'Add your business and payout details on Stripe’s secure onboarding page. Stripe stores your bank details; this website never asks for your secret key.'}</p><ol><li>Connect Stripe and complete your business and bank information.</li><li>Check account status until card payments are enabled.</li><li>Add a class and set its total upfront price.</li><li>Share your page. Customers pay that exact price in Stripe Checkout.</li></ol><p>Example: a block priced at £90 creates a £90 charge for all its sessions. Stripe fees are deducted from your payout; there is no added booking fee.</p><div class="list-actions"><button class="btn accent" data-action="stripe-connect">${data.pt.stripe_connected?'Continue Stripe setup':'Connect my Stripe account'} ↗</button>${data.pt.stripe_connected?'<button class="btn outline" data-action="stripe-status">Check account status</button>':''}</div><p class="fine">Current mode: ${modeName(config.payment_mode)}. ${config.payment_mode==='stripe_live'?'Customers make genuine purchases with real cards.':'Use Stripe sandbox details and test cards only.'} The platform owner configures Stripe Connect. Test and live accounts are separate.</p></div>`;}else{if(tab==='overview')content=heading('Your coaching platform, connected.','Give each trainer their own branded site, classes and client experience.','<button class="btn accent" data-action="new-pt">Create a PT account +</button>')+stats([['PT accounts',data.stats.pts,'Individually branded pages'],['Customer accounts',data.stats.customers,'Shared sign-in across trainers'],['Confirmed bookings',data.stats.confirmed,'All payment modes'],['Reply library',20,'Random no-show encouragement']])+trainerCards(data.pts);else if(['trainers','branding'].includes(tab))content=heading(tab==='branding'?'Their coaching. Their own look.':'Give every PT their own space.',tab==='branding'?'Customise each page name, address, colour palette, copy and training highlights.':'Create PT accounts with a unique named home page.','<button class="btn accent" data-action="new-pt">Create PT account +</button>')+trainerCards(data.pts,tab==='branding');else if(tab==='stripe')content=await stripeSetupView();else if(tab==='bookings')content=heading('Bookings and refunds.','Only verified Stripe payment notifications confirm bookings. Refunds return to the original payment method.')+bookingTable(data.bookings);else if(tab==='classes')content=heading('Every trainer. Every block.','Manage custom programme lengths and individual class dates.','<button class="btn accent" data-action="new-block">Add a class or block +</button>')+`<div class="card-grid">${data.pts.flatMap(pt=>pt.blocks.map((b,i)=>classCard({...b,title:pt.brand_name+' / '+b.title},i,{manage:true}))).join('')}</div>`;else if(tab==='messages')content=heading('Platform email previews.','No-show follow-ups and confirmations, with delivery status.')+messageTable(data.outbox);else if(tab==='quotes')content=heading('Twenty ways to encourage a return.','Each no-show follow-up chooses one original message at random. Repeat attendance edits do not send duplicate follow-ups.')+`<div class="quote-grid">${data.quotes.map((q,i)=>`<div class="quote-card"><small>REPLY ${String(i+1).padStart(2,'0')}</small>${esc(q)}</div>`).join('')}</div>`;}
if(!content){navigate('/dashboard');return;}$('app').innerHTML=dashboardShell(tab,content);document.title=(me.role==='admin'?'Platform admin':me.role==='pt'?'Trainer workspace':'My bookings')+' — FITSPACE';}
async function renderRoute(){const version=++routeVersion;try{await refreshMe();const path=location.pathname;if(path==='/forgot-password'){$('app').innerHTML=forgotPasswordView();document.title='Reset your password — FITSPACE';return;}if(path==='/reset-password'){if(location.hash){resetToken=location.hash.slice(1);history.replaceState(null,'',location.pathname);} $('app').innerHTML=resetPasswordView();document.title='Choose a new password — FITSPACE';return;}if(path==='/dashboard')return await renderDashboard(version);const check=path.match(/^\/(checkout|booking)\/([^/]+)$/);if(check)return await renderCheckout(check[2],version,check[1]==='booking');if(path==='/trainers')return await renderDirectory(version);if(path==='/login'||path==='/signup'){await renderDirectory(version);authModal(path.slice(1),'dashboard');return;}const match=path.match(/^\/pt\/([a-z0-9-]+)$/);if(match||path==='/'){if(!match&&!config.default_slug)return await renderDirectory(version);return await renderHome(match?match[1]:config.default_slug,version);}$('app').innerHTML=`<div class="container">${brandHeader()}<div class="loading"><h2>This page is not available.</h2><a class="btn" href="/trainers" data-route>Find a trainer</a></div></div>`;}catch(e){$('app').innerHTML=`<div class="container">${brandHeader()}<div class="loading"><h2>${e.status===404?'This training page is not available.':'We could not load your training space.'}</h2><p>${esc(e.message)}</p><a href="/trainers" class="btn" data-route>Find a trainer</a></div></div>`;}}
function nextMonday(){const day=new Date();day.setUTCDate(day.getUTCDate()+((8-day.getUTCDay())%7||7));return day.toISOString().slice(0,10)+'T18:30';}
function allBlocks(){return me.role==='pt'?dashboardData.blocks:dashboardData.pts.flatMap(p=>p.blocks);}
function blockForm(block=null,ptId=null){const first=block?.sessions[0]?.starts_at||nextMonday(),n=block?.sessions.length||6;const ptOptions=me.role==='admin'?`<label class="wide-field">Trainer<select name="pt_id" ${block?'disabled':''}>${dashboardData.pts.map(p=>`<option value="${p.id}" ${(ptId||block?.pt_id)===p.id?'selected':''}>${esc(p.brand_name)}</option>`).join('')}</select></label>`:'';modal(block?'Make this class your own.':'Build a class that fits.',`<p>Choose any programme length. Use one session for a single class, or add dates for a block. Dates are locked once bookings exist.</p><form data-form="block"><input type="hidden" name="id" value="${block?.id||''}"><div class="form-grid">${ptOptions}<label class="wide-field">Class or block name<input name="title" value="${esc(block?.title||'')}" required minlength="3" maxlength="100" placeholder="e.g. Eight-week strength club"></label><label class="wide-field">What customers can expect<textarea name="description" required minlength="5" maxlength="1000">${esc(block?.description||'Coached strength and conditioning, with support to help you progress at your own pace.')}</textarea></label><label class="wide-field">Venue<input name="venue" value="${esc(block?.venue||'')}" required minlength="3" maxlength="160" placeholder="Studio name and address"></label><label>Total upfront price (£)<input name="price" type="number" min="1" max="10000" step="0.01" value="${block?block.price_pence/100:90}" required><small class="form-help">Covers every session in this booking.</small></label><label>Maximum participants<input name="capacity" type="number" min="1" max="100" value="${block?.capacity||15}" required><small class="form-help">Choose 1–100 participants. Confirmed bookings and active checkouts count toward this limit.</small></label></div><div class="session-generator"><label>First date & time<input id="firstSession" type="datetime-local" value="${first}" required></label><label>Number of weeks / sessions<input id="sessionCount" type="number" min="1" max="52" value="${n}" required></label><label>Minutes<input id="sessionMinutes" type="number" min="15" max="240" step="5" value="${block?.sessions[0]?.duration_minutes||60}" required></label></div><button type="button" class="btn outline small" data-action="generate-dates">Generate weekly dates</button><p class="fine">All times are Europe/London. Edit each date below if your schedule varies. Blocks are not restricted to six weeks.</p><div id="sessionEditor" class="session-editor"></div><label class="check-label"><input name="published" type="checkbox" ${!block||block.published?'checked':''}><span>Show this class on the customer's booking page.</span></label>${block?`<label class="check-label"><input name="closed" type="checkbox" ${block.closed?'checked':''}><span>Close new bookings. Existing confirmed bookings and attendance stay available.</span></label>`:''}<button type="submit" class="btn accent full">${block?'Save class changes':'Create class or block'} ↗</button></form>`,{wide:true,eyebrow:'YOUR CLASSES / CUSTOM SCHEDULE'});renderSessionEditor(block?.sessions||weeklyDates(first,n,60));}
function weeklyDates(first,count,minutes){if(!first||count<1||count>52)throw new Error('Choose a first date and 1–52 sessions.');const date=first.slice(0,10),time=first.slice(11);return Array.from({length:count},(_,i)=>{const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+i*7);return {starts_at:d.toISOString().slice(0,10)+'T'+time,duration_minutes:minutes};});}
function renderSessionEditor(sessions){$('sessionEditor').innerHTML=sessions.map((s,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><label class="sr-only" for="sessionDate${i}">Session ${i+1} date and time</label><input id="sessionDate${i}" name="session_date" aria-label="Session ${i+1} date and time" type="datetime-local" value="${s.starts_at}" required><label class="duration-label">Minutes<input name="session_minutes" aria-label="Session ${i+1} duration in minutes" type="number" min="15" max="240" value="${s.duration_minutes}" required></label></div>`).join('');}
function brandForm(pt=null){const d=pt||{brand_name:'YOUR TRAINING CLUB',slug:'your-training-club',tagline:'Train with purpose. Grow in confidence.',description:'Coached training, a supportive group and a regular routine to help you make progress at your own pace.',about:'Build strength, practise better technique and improve your fitness with personal coaching and a small group to support you.',accent:'#ffd43b',background:'#ffffff',foreground:'#111111',features:['Strength & conditioning','Small groups. Personal coaching.','Progress at your own pace'],published:true};modal(pt?'Their coaching. Their own look.':'Create a trainer’s own space.',`<p>${pt?'Change the branding, text and named page for this PT. Changing the page address means old links will no longer work.':'The PT gets a separate account and their own named client page. You control the starting brand and content.'}</p><form data-form="brand"><input type="hidden" name="id" value="${pt?.id||''}"><div class="form-grid">${!pt?'<label>PT’s name<input name="owner_name" required minlength="2" maxlength="80" placeholder="e.g. Alex Morgan"></label><label>PT’s email<input name="email" type="email" required placeholder="coach@example.com"></label>':''}<label>Site name<input name="brand_name" value="${esc(d.brand_name)}" required minlength="3" maxlength="70"></label><label>Named page address<input name="slug" value="${esc(d.slug)}" required pattern="[a-z0-9]+(-[a-z0-9]+)*" minlength="3" maxlength="50"><small class="form-help">Your app address /pt/<span id="slugPreview">${esc(d.slug)}</span></small></label><label class="wide-field">Home page headline<input name="tagline" value="${esc(d.tagline)}" required minlength="5" maxlength="120"></label><label class="wide-field">Home page introduction<textarea name="description" required minlength="10" maxlength="700">${esc(d.description)}</textarea></label><label class="wide-field">Training and improvement information<textarea name="about" required minlength="10" maxlength="1200">${esc(d.about)}</textarea></label><label class="wide-field">Training highlights (one per line, maximum 3)<textarea name="features" required>${esc(d.features.join('\n'))}</textarea></label><div class="triple"><label>Highlight colour<input type="color" name="accent" value="${d.accent}"></label><label>Page background<input type="color" name="background" value="${d.background}"></label><label>Text colour<input type="color" name="foreground" value="${d.foreground}"></label></div></div><div class="demo-choices"><button type="button" class="btn outline small" data-action="theme-preset" data-theme="yellow">Black / white / yellow</button><button type="button" class="btn outline small" data-action="theme-preset" data-theme="coral">Warm studio</button><button type="button" class="btn outline small" data-action="theme-preset" data-theme="blue">Blue & white</button><button type="button" class="btn outline small" data-action="theme-preset" data-theme="dark">Dark training club</button></div><div class="brand-preview" id="brandPreview"><strong></strong><p></p></div><label class="check-label"><input name="published" type="checkbox" ${d.published?'checked':''}><span>Make this trainer page available on the public site.</span></label><button type="submit" class="btn accent full">${pt?'Save trainer branding':'Create PT account & page'} ↗</button></form>`,{wide:true,eyebrow:'PLATFORM ADMIN / PT BRANDING'});updateBrandPreview();}
function updateBrandPreview(){const form=$('modalBody').querySelector('form[data-form=brand]');if(!form)return;const preview=$('brandPreview');preview.style.background=form.elements.background.value;preview.style.color=form.elements.foreground.value;preview.style.borderColor=form.elements.accent.value;preview.querySelector('strong').textContent=form.elements.brand_name.value;preview.querySelector('p').textContent=form.elements.tagline.value;$('slugPreview').textContent=form.elements.slug.value;}
function passwordForm(){modal('Make your account your own.',`<p>Changing your password signs out your other sessions.</p><form data-form="password"><div class="form-grid"><label class="wide-field">Current password<input name="current_password" type="password" required autocomplete="current-password"></label><label class="wide-field">New password<input name="new_password" type="password" minlength="12" maxlength="200" required autocomplete="new-password"><small class="form-help">At least 12 characters.</small></label></div><button class="btn accent full" type="submit">Save my new password ↗</button></form>`);}
function showEmail(row){modal(row.subject,`<p>To: ${esc(row.recipient)}<br>Status: ${row.status==='preview'?'Preview only — no email was sent':esc(row.status)}</p><div class="email-body">${esc(row.body)}</div>`,{eyebrow:'CUSTOMER FOLLOW-UP'});}
let pendingAttendance=null,pendingCancel=null;
document.addEventListener('click',async event=>{const link=event.target.closest('a[data-route]');if(link){event.preventDefault();navigate(link.getAttribute('href'));return;}const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;try{if(action==='forgot-password'){if($('modal').open)$('modal').close();navigate('/forgot-password');}else if(action==='close-modal')$('modal').close();else if(action==='login'||action==='signup')authModal(action);else if(action==='logout'){await api('/api/auth/logout',{method:'POST',body:{}});me=null;csrf=null;authIntent=null;pendingBlock=null;navigate('/');toast('You are signed out.');}else if(action==='book')bookingModal(publicData.blocks.find(b=>b.id===el.dataset.id));else if(action==='pay-demo'){el.disabled=true;const data=await api('/api/bookings/'+el.dataset.id+'/pay',{method:'POST',body:{result:el.dataset.result}});navigate('/booking/'+data.booking.id);toast(data.booking.status==='paid'?'Your test booking is confirmed.':'Test payment declined. The place has been released.');}else if(action==='resume-stripe'){el.disabled=true;const result=await api('/api/bookings/'+el.dataset.id+'/checkout',{method:'POST',body:{}});location.assign(result.url);}else if(action==='refund-booking'){const id=el.dataset.id;const b=dashboardData?.bookings?.find(b=>b.id===id);modal('Refund this payment?',`<p>Refund ${b?money(b.amount_pence-b.refunded_pence):'the remaining balance'} to the original card? ${config.payment_mode==='stripe_live'?'This returns real money.':'This is a sandbox refund; no real money moves.'} A full successful refund cancels the booking and releases its place.</p><button class="btn accent full" data-action="confirm-refund" data-id="${id}" data-token="${uid()}">Confirm refund</button>`);}else if(action==='confirm-refund'){el.disabled=true;const result=await api('/api/bookings/'+el.dataset.id+'/refund',{method:'POST',body:{request_token:el.dataset.token}});$('modal').close();await renderRoute();toast(result.refund_status==='succeeded'?'Payment refunded.':'Refund submitted. Its status will update after Stripe responds.');}else if(action==='cancel-booking'){pendingCancel=el.dataset.id;modal('Cancel this booking?',`<p>For a Stripe checkout, the place is released only after Stripe confirms it is no longer payable. Completed payments must be refunded by the trainer.</p><div class="modal-actions"><button class="btn outline" data-action="close-modal">Keep booking</button><button class="btn danger" data-action="confirm-cancel">Cancel booking</button></div>`);}else if(action==='confirm-cancel'){await api('/api/bookings/'+pendingCancel+'/cancel',{method:'POST',body:{}});$('modal').close();await renderRoute();toast('Booking cancelled. The place is available again.');}else if(action==='refresh-route')await renderRoute();else if(action==='new-block')blockForm(null,el.dataset.pt||null);else if(action==='edit-block')blockForm(allBlocks().find(b=>b.id===el.dataset.id));else if(action==='generate-dates')renderSessionEditor(weeklyDates($('firstSession').value,Number($('sessionCount').value),Number($('sessionMinutes').value)));else if(action==='new-pt')brandForm();else if(action==='edit-brand')brandForm(dashboardData.pts.find(p=>p.id===el.dataset.id));else if(action==='theme-preset'){const presets={yellow:['#ffd43b','#ffffff','#111111'],coral:['#fb9374','#faf6f2','#272727'],blue:['#438bff','#ffffff','#101c34'],dark:['#ffd43b','#111111','#ffffff']};const [accent,bg,fg]=presets[el.dataset.theme],form=$('modalBody').querySelector('form');form.elements.accent.value=accent;form.elements.background.value=bg;form.elements.foreground.value=fg;updateBrandPreview();}else if(action==='password')passwordForm();else if(action==='email-preview')showEmail(dashboardData.outbox.find(r=>r.id===el.dataset.id));else if(action==='attendance'){pendingAttendance={booking_id:el.dataset.booking,session_id:el.dataset.session,status:el.dataset.status};if(el.dataset.status==='no_show'){const booking=dashboardData.bookings.find(b=>b.id===el.dataset.booking);modal('Send a little encouragement.',`<p>Mark ${esc(booking.customer_name)} as a no-show for this session?</p><div class="info-box"><strong>Sorry we missed you at class!</strong><br>To: ${esc(booking.customer_email)}<br>One motivational reply is selected at random from the 20-message library. ${config.email_mode==='preview'?'The email will be saved as a preview; it will not be sent.':'The email will be queued for your configured delivery service.'}<br>Repeated marking does not create another email.</div><div class="modal-actions"><button class="btn outline" data-action="close-modal">Keep attendance</button><button class="btn accent" data-action="confirm-attendance">Mark no show</button></div>`);}else await markAttendance();}else if(action==='confirm-attendance')await markAttendance();else if(action==='pt-stripe-check'){await api('/api/pt/stripe/check',{method:'POST',body:{mode:el.dataset.mode}});await renderRoute();toast('Stripe account status checked. Validate checkout and refund permissions in sandbox.');}else if(action==='pt-stripe-enable'){const mode=el.dataset.mode;modal(mode==='stripe_live'?'Enable genuine payments?':'Enable sandbox payments?',`<p>${mode==='stripe_live'?'Customers will be charged real money when the site is in live mode. Confirm you have completed sandbox tests and are ready to sell genuine services.':'Enable test payments for your saved sandbox account. Complete a booking and full refund to verify the integration.'}</p><button class="btn accent full" data-action="pt-stripe-enable-confirm" data-mode="${mode}">Confirm ${mode==='stripe_live'?'live':'sandbox'} enablement</button>`);}else if(action==='pt-stripe-enable-confirm'){await api('/api/pt/stripe/enable',{method:'POST',body:{mode:el.dataset.mode,live_ack:el.dataset.mode==='stripe_live'}});$('modal').close();await renderRoute();toast('Payments enabled for this account and mode.');}else if(action==='pt-stripe-pause'){await api('/api/pt/stripe/disconnect',{method:'POST',body:{mode:el.dataset.mode}});await renderRoute();toast('New payments paused. Existing checkout, refund and webhook processing remain available.');}else if(action==='pt-stripe-remove'){modal('Remove saved Stripe credentials?',`<p>This stops automated payment updates and refunds for this account. Historical bookings remain. Manage remaining payments directly in Stripe, or reconnect the same account later. Active checkouts must be cancelled or expire first. Revoke the key and delete the webhook in Stripe separately.</p><form data-form="pt-stripe-remove"><input type="hidden" name="mode" value="${el.dataset.mode}"><label>Type ${esc(el.dataset.account)} to confirm<input name="confirm_account" required autocomplete="off"></label><button class="btn danger full" type="submit">Remove credentials</button></form>`);}else if(action==='stripe-check-owner'){const r=await api('/api/admin/stripe/check',{method:'POST',body:{}});modal('Your Stripe account',`<dl class="summary-lines"><div><dt>Account</dt><dd>${esc(r.id)}</dd></div><div><dt>Business</dt><dd>${esc(r.name||'Not provided')}</dd></div><div><dt>Email</dt><dd>${esc(r.email||'Not provided')}</dd></div><div><dt>Card payments</dt><dd>${r.charges_enabled?'Enabled':'Setup required'}</dd></div><div><dt>Mode</dt><dd>${modeName(r.mode)}</dd></div></dl>`);}else if(action==='stripe-link-owner'){const pt=$('stripeTrainer').value;if(!pt)throw new Error('Choose a trainer first.');modal('Link the owner’s Stripe account?',`<p>This trainer will receive payments in the Stripe account configured by the server key. Other trainers should connect their own accounts from Payments.</p><button class="btn accent full" data-action="stripe-link-confirm" data-pt="${esc(pt)}">Link this account</button>`);}else if(action==='stripe-link-confirm'){await api('/api/admin/stripe/link',{method:'POST',body:{pt_id:el.dataset.pt}});$('modal').close();await renderRoute();toast('Stripe account linked. Check its status before taking payments.');}else if(action==='stripe-connect'){el.disabled=true;try{const result=await api('/api/pt/stripe/connect',{method:'POST',body:{}});location.assign(result.url);}finally{el.disabled=false;}}else if(action==='stripe-status'){const result=await api('/api/pt/stripe/status',{method:'POST',body:{}});await renderRoute();toast(result.ready?'Stripe account is ready for payments in this mode.':'Stripe setup is incomplete. Continue onboarding.');}}catch(e){el.disabled=false;if($('modal').open)modalError(e.message);else toast(e.message);}});
async function markAttendance(){const selected={...pendingAttendance},result=await api('/api/attendance',{method:'POST',body:selected});if($('modal').open)$('modal').close();dashboardData=await api('/api/dashboard');renderRoster(selected.session_id);if(result.email){showEmail({...result.email,recipient:dashboardData.bookings.find(b=>b.id===selected.booking_id).customer_email});}else toast(selected.status==='attended'?'Attendance marked as present.':'Attendance cleared.');}
document.addEventListener('submit',async event=>{const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();const kind=form.dataset.form,fd=new FormData(form),fields=Object.fromEntries(fd.entries()),button=form.querySelector('button[type=submit]');if(button)button.disabled=true;try{if(kind==='pt-stripe'){await api('/api/pt/stripe/credentials',{method:'POST',body:fields});form.reset();await renderRoute();toast('Account verified and credentials saved. Configure the webhook, then enable payments.');}else if(kind==='pt-stripe-remove'){await api('/api/pt/stripe/disconnect',{method:'POST',body:{...fields,erase:true}});$('modal').close();await renderRoute();toast('Saved credentials removed. Historical bookings remain.');}else if(kind==='forgot-password'){const result=await api('/api/auth/forgot-password',{method:'POST',body:{email:fields.email}});$('resetFeedback').textContent=result.message;}else if(kind==='reset-password'){if(fields.new_password!==fields.confirm_password)throw new Error('Your passwords do not match.');await api('/api/auth/reset-password',{method:'POST',body:{token:resetToken,new_password:fields.new_password}});resetToken='';me=null;csrf=null;navigate('/login');toast('Password reset. Sign in with your new password.');}else if(kind==='login'||kind==='signup'){const result=await api('/api/auth/'+kind,{method:'POST',body:{...fields,demo_acknowledged:fd.has('demo_acknowledged')}});me=result.user;csrf=result.csrf;$('modal').close();if(authIntent==='book'&&pendingBlock){const block=pendingBlock;authIntent=null;await renderRoute();bookingModal(block);}else{const destination=authIntent==='return'&&authReturnPath?authReturnPath:'/dashboard';authIntent=null;authReturnPath=null;navigate(destination);toast('You are signed in.');}}else if(kind==='reserve'){const result=await api('/api/bookings',{method:'POST',body:fields});$('modal').close();if(result.url.startsWith('/'))navigate(result.url);else location.assign(result.url);}else if(kind==='password'){const result=await api('/api/auth/password',{method:'POST',body:fields});csrf=result.csrf;$('modal').close();await renderRoute();toast('Your password has been updated.');}else if(kind==='block'){const dates=Array.from(form.querySelectorAll('[name=session_date]')).map(x=>x.value),minutes=Array.from(form.querySelectorAll('[name=session_minutes]')).map(x=>Number(x.value));const payload={...fields,price_pence:Math.round(Number(fields.price)*100),capacity:Number(fields.capacity),published:fd.has('published'),closed:fd.has('closed'),sessions:dates.map((starts_at,i)=>({starts_at,duration_minutes:minutes[i]}))};await api(fields.id?'/api/blocks/'+fields.id:'/api/blocks',{method:fields.id?'PUT':'POST',body:payload});$('modal').close();await renderRoute();toast(fields.id?'Class changes saved.':'Your class is ready to book.');}else if(kind==='brand'){const payload={...fields,published:fd.has('published'),features:fields.features.split('\n').map(s=>s.trim()).filter(Boolean)};const result=await api(fields.id?'/api/admin/pts/'+fields.id:'/api/admin/pts',{method:fields.id?'PUT':'POST',body:payload});$('modal').close();await renderRoute();if(!fields.id)modal('Their training space is ready.',`<p>The PT account and named page have been created. Save these temporary sign-in details and share them privately with the PT.</p><div class="credential"><strong>${esc(result.email)}</strong><br>Temporary password:<br><code>${esc(result.temporary_password)}</code></div><div class="info-box">This password is shown only now. The PT must change it before managing classes. No invitation email was sent.</div><a class="btn accent full" href="${result.path}" data-route>View their new home page ↗</a>`);else toast('Trainer branding saved.');}}catch(e){if($('resetFeedback'))$('resetFeedback').textContent=e.message;else if($('modal').open)modalError(e.message);else toast(e.message);}finally{if(button)button.disabled=false;}});
document.addEventListener('input',event=>{if(event.target.id==='bookingSearch'){const q=event.target.value.toLowerCase();document.querySelectorAll('#bookingsBody tr').forEach(row=>row.hidden=!row.dataset.search.includes(q));}if(event.target.closest('form[data-form=brand]'))updateBrandPreview();});
document.addEventListener('change',event=>{if(event.target.id==='attendanceSession')renderRoster(event.target.value);});
window.addEventListener('popstate',renderRoute);renderRoute();
